static void InitNumberBitsSet(void)
{
  for (unsigned int i = 0; i < 16; ++i)
    number_bits_set[i] = num_bits_set(i);
}

static int activate_deflect(int player, int card, int event, target_definition_t *td)
{
  return deflect_one_target(player, card, event, td);
}

static int check_for_equipment_targets_impl(int player, int card, target_definition_t *td)
{
  td->flags |= 5;
  return can_target(td);
}

static int goad(int player, int card, int t_player, int t_card)
{
  return create_targetted_legacy_effect(player, card, goad_effect, t_player, t_card);
}

static int find_imprint_legacy(int player, int card)
{
  int index = 0;
  return find_imprint_legacy_next(player, card, &index);
}

static void disable_legend_rule_impl(int t_player)
{
  if (((unsigned int)t_player & 0xfffffffdU) == 0)
    player_bits[0] = (player_bits_t)((uint32_t)player_bits[0] | PB_LEGEND_RULE_DISABLED);
  if ((unsigned int)t_player - 1U < 2)
    player_bits[1] = (player_bits_t)((uint32_t)player_bits[1] | PB_LEGEND_RULE_DISABLED);
}

static void phyrexians(int player, int card, event_t event, int amount)
{
  etb_ability(player, card, event, RESOLVE_TRIGGER_MANDATORY);
  if (event == EVENT_ETB)
  {
    lose_life(player, amount);
    draw_cards(player, amount);
  }
}

static int is_this_dying_or_being_exiled(int player, int card)
{
  return in_play(player, card) &&
         (unsigned char)(get_card_instance(player, card)->kill_code - 1) <= 3;
}

static void generate_encore_token(int player, int card, int csvid)
{
  token_generation_t token;
  default_token_definition(player, card, csvid, &token);
  token.legacy = 1;
  token.special_code_for_legacy = encore_legacy;
  generate_token(&token);
}

static int get_updated_casting_cost_with_cost_mod(int player, int card, int iid,
                                                   event_t event, int cless, int cost_mod)
{
  int cost = true_get_updated_casting_cost(player, card, iid, event, cless - cost_mod);
  return cost < 0 ? 0 : cost;
}

static int add_force_a_subtype_permanently(int player, int card, int t_player, int t_card,
                                            subtype_t subtype, int mode)
{
  int legacy = create_targetted_legacy_effect(player, card, add_force_a_subtype_permanently_legacy,
                                             t_player, t_card);
  card_instance_t *instance = get_card_instance(player, legacy);
  instance->targets[1].player = mode;
  instance->targets[1].card = subtype;
  instance->token_status = 0x10000;
  return legacy;
}

static int add_force_a_subtype_until_eot_impl(int player, int card, int t_player, int t_card,
                                             subtype_t subtype, int mode)
{
  int legacy = create_targetted_legacy_effect(player, card, add_force_a_subtype_until_eot_legacy,
                                             t_player, t_card);
  get_card_instance(player, legacy)->targets[1].player = mode;
  get_card_instance(player, legacy)->targets[1].card = subtype;
  return legacy;
}

static char *destr_read_a_line(char **raw_file)
{
  char *line = *raw_file;
  char *newline = strchr(line, '\n');
  if (!newline)
    return NULL;
  *newline = '\0';
  *raw_file = newline + 1;
  return line;
}

static int can_legally_play_iid_now_lite(int player, int internal_card_id, event_t event)
{
  if (!(cards_data[internal_card_id].type & (TYPE_INSTANT | TYPE_INTERRUPT)) &&
      !can_sorcery_be_played(player, event))
    return 0;
  return !(cards_data[internal_card_id].type & TYPE_LAND) ||
         (!(land_can_be_played & 1) && player == current_turn);
}

static int retrieve_stored_iids_and_tou(card_instance_t *inst, int16_t *iids, int16_t *tou, int pos)
{
  int count = 0;
  for (; pos < 10; ++pos)
    if (inst->targets[pos].player != -1)
    {
      iids[count] = (int16_t)inst->targets[pos].player;
      tou[count] = (int16_t)inst->targets[pos].card;
      ++count;
    }
  return count;
}

static void clear_stored_iids_and_tou(card_instance_t *inst, int pos)
{
  for (; pos < 10; ++pos)
  {
    inst->targets[pos].card = -1;
    inst->targets[pos].player = -1;
  }
}

static int can_pay_aftermath(int player, int iid, event_t event, int colorless,
                             int black, int blue, int green, int red, int white)
{
  int cost = get_updated_casting_cost(player, -1, iid, event, colorless);
  return has_mana_multi(player, cost, black, blue, green, red, white);
}

static void exile_and_give_elemental(int player, int card, int t_player, int t_card)
{
  kill_card(t_player, t_card, KILL_EXILE);
  token_generation_t token;
  default_token_definition(player, card, CARD_ID_ELEMENTAL, &token);
  token.tou = 4;
  token.pow = 4;
  token.color_forced = 0x14;
  token.t_player = t_player;
  generate_token(&token);
}

static void create_hofri_token(int player, int card, int iid, int owner, int original_iid)
{
  token_generation_t token;
  default_token_definition(player, card, cards_data[iid].id, &token);
  token.action_argument = (int32_t)(((uint32_t)original_iid << 4) | (uint32_t)owner);
  token.special_code_on_generation = add_hofry_legacy;
  generate_token(&token);
}

static int create_targetted_legacy_effect_replace(int player, int card, CardFunction func_ptr,
                                                  int target_player_id, int target_card)
{
  target_t previous = find_repeat_legacy_effect_alt(player, card, func_ptr,
                                                   target_player_id, target_card, -1, player);
  if (previous.card != -1)
    kill_card(player, previous.card, KILL_EXILE);
  return create_targetted_legacy_effect(player, card, func_ptr, target_player_id, target_card);
}

static int find_any_attached_legacy_effect(CardFunction func_ptr, int target_player_id, int target_card)
{
  for (int card = 0; card < active_cards_count[target_player_id]; ++card)
  {
    card_instance_t *instance = in_play(target_player_id, card);
    if (instance && instance->internal_card_id == LEGACY_EFFECT_CUSTOM &&
        instance->info_slot_fn == func_ptr && instance->damage_target_player == target_player_id &&
        instance->damage_target_card == target_card)
      return card;
  }
  return -1;
}

static void validate_imprinted_card(int player, int card)
{
  int legacy = find_imprint_legacy(player, card);
  if (legacy >= 0)
  {
    card_instance_t *instance = get_card_instance(player, legacy);
    if (find_iid_in_rfg(instance->targets[0].player, instance->targets[0].card) == -1)
      kill_card(player, legacy, KILL_EXILE);
  }
}

static void archon_of_cruelty_effect(int player, int card)
{
  if (opponent_is_valid_target(player, card))
  {
    int opponent = 1 - player;
    player_sacrifices_a_permanent(player, card, opponent, 0x102, SAC_CAUSED);
    new_multidiscard(opponent, 1, player, 2);
    lose_life(opponent, 3);
    draw_cards(player, 1);
    gain_life(player, 3);
  }
}

